// 정보 패널: NAV 객체, subs의 카테고리, groups/ subgroups의 각 객체에
// description(짧은 설명), detail(상세 설명)을 입력합니다. detail의 \n은 줄바꿈입니다.
// \n\n = 새로운 아이디어 박스
// 【제목】\n = 새로운 섹션 생성
// [[section:제목]] = 새로운 섹션 생성 (【제목】을 일반 글자로 표시 가능),섹션종료 없어도 추가로 [[section:제목2]] 입력시 섹션 가능
// [[/section]] = 섹션 종료 (생략 가능)
// 주의: [[section:]] 사용 시 같은 detail 안의 【】는 일반 글자로 취급됨.

/* ══════════════════════════════════════════════
   캐릭터 데이터
   - CHARACTER_NAV  : 캐릭터 탭 네비게이션 정의
   - CHARACTER_CARDS: 캐릭터 탭 카드 데이터  

섹션 헤더
{ type: 'section' ,  label: ' 헤더 — 추가 설명 ' },  

카드 코드
{ name:'이름' ,img:'images/Peep.png', subImg:'images/Giant_Elf.jpg',  desc:'내용' ,   detail:'【상세】 정보\n【상세】\n\n내용'  },


layoutType: '3',   ← 여기에 5/4/3/2 중 하나를 입력하면 그룹 카드 목록에 고정 적용됨. 카드 가로 개수, 기본=3

그룹 버튼 이미지
      img: 'images/character/group/animal.jpg',    

    detailMode: 'AB',
    detailA: ' ',
    detailB: ' '},


══════════════════════════════════════════════════════════════════════════════════════════ */

